"""Design artifact: factor-grid validator + compute/API cost model (pure stdlib).
Nothing here is an experimental result; it validates harness config logic and projects cost
using PLACEHOLDER throughput constants."""
import json, csv, itertools, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
CFG = json.load(open(os.path.join(HERE, "..", "configs", "factors.json")))

# ---- placeholders for cost model (labelled, not source numbers) ----
TOK_IN, TOK_OUT = 512, 256                # avg tokens per target query
THROUGHPUT_TPS = 1200.0                   # tokens/s/GPU, vLLM-class 8B bf16, placeholder
API_TOKEN_PRICE = 5.0                     # $/1M tokens blended attacker+judge, placeholder
DEFENSE_OVERHEAD = 1.15                   # D1/D2 filter+judge extra forward passes
B, S = 100, 3                             # behaviors x seeds

def pair_queries(L):  return CFG["attacker_strength"][L]["pair_target_queries"]
def autodan_evals(L):
    c = CFG["attacker_strength"][L]
    return c["autodan_pop"] * (c["autodan_gen"] + 1)   # + initial population scoring

def queries_per_behavior(style, L):
    return pair_queries(L) if style == "PAIR" else autodan_evals(L)

def cells():
    styles = CFG["attack_style"]["levels"]
    Ls = list(CFG["attacker_strength"]); Ds = list(k for k in CFG["defense_strength"])
    Ms = list(CFG["memory"])
    for c in itertools.product(styles, Ls, Ds, Ms):
        yield c

def main():
    cs = list(cells())
    keys = [(s, l, d, m) for s, l, d, m in cs]
    assert len(keys) == len(set(keys)), "duplicate cells"
    n_cells = len(keys)
    out = os.path.join(HERE, "..", "cells.csv")
    rows = []
    tot_tokens = 0.0
    for (st, L, D, M) in cs:
        q = queries_per_behavior(st, L) * B * S
        ov = DEFENSE_OVERHEAD if D != "D0" else 1.0
        toks = q * (TOK_IN + TOK_OUT) * ov
        tot_tokens += toks
        gh = toks / (THROUGHPUT_TPS * 3600.0)
        # attacker+judge API-equivalent tokens: attacker gens + judge calls on subset
        ag = CFG["attacker_strength"][L].get("pair_attacker_gens", 0) if st == "PAIR" else 0
        judge_calls = B * S * min(q, 25)  # rule-match first, judge capped at 25/behavior
        api_tok = (ag * B * S + judge_calls) * 1500
        rows.append(dict(style=st, strength=L, defense=D, memory=M,
                         target_queries_per_behavior=q // (B * S),
                         target_tokens=int(toks), gpu_hours=round(gh, 2),
                         api_tokens=int(api_tok), api_usd=round(api_tok / 1e6 * API_TOKEN_PRICE, 1)))
    with open(out, "w", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
    gpu = sum(r["gpu_hours"] for r in rows); api = sum(r["api_usd"] for r in rows)
    print(f"cells={n_cells} (2x3x4x3 with D1 split into 2 components = full frame)")
    print(f"target-tokens total = {tot_tokens/1e9:.2f}B ; GPU-hours = {gpu:.0f}")
    print(f"attacker+judge API-equivalent cost = ${api:,.0f} at ${API_TOKEN_PRICE}/1M tok")
    print(f"per-cell mean GPU-hours = {gpu/n_cells:.2f}")
    return rows

if __name__ == "__main__":
    main()
EOF
