"""Design artifact: pre-registration power check for the PRIMARY mixed-effects logistic model.
Simulates DATA-FOR-DESIGN-PURPOSES ONLY (synthetic Bernoulli outcomes under stated
assumptions) to size behaviors x seeds. NOT experimental results; no model was run.

Target effect: attacker-strength x defense-strength 2-way interaction on the log-odds scale,
collapsed to design endpoints (L1 vs L3; D0 vs D2). Random intercepts for behavior (SD 1.0)
and seed (SD 0.3) are simulated IN; inference uses a behavior-clustered (sandwich) Wald test
on the interaction coefficient of the population-average logistic fit.
"""
import math, random, multiprocessing as mp

TAU_SIG_B, TAU_SIG_S = 1.0, 0.3
Z_CRIT = 1.959964
K = 4

def sig(x):
    if x < -35: return math.exp(x) if x > -700 else 0.0
    return 1.0/(1.0+math.exp(-x))

def inv(M):
    n = len(M)
    A = [list(M[i]) + [1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(A[r][c]))
        if abs(A[p][c]) < 1e-11: raise ZeroDivisionError("singular")
        A[c], A[p] = A[p], A[c]
        pv = A[c][c]; A[c] = [x/pv for x in A[c]]
        for r in range(n):
            if r != c and A[r][c] != 0.0:
                f = A[r][c]; A[r] = [a - f*b for a, b in zip(A[r], A[c])]
    return [row[n:] for row in A]

def sim_one(args):
    B, S, bt, seed = args
    rng = random.Random(seed)
    b0, ba, bd, bad = bt
    X, y, csizes = [], [], []
    cellx = [(0,0),(1,0),(0,1),(1,1)]
    for bi in range(B):
        ub = rng.gauss(0, TAU_SIG_B); cs = 0
        for s in range(S):
            us = rng.gauss(0, TAU_SIG_S)
            for (xa, xd) in cellx:
                eta = b0 + ba*xa + bd*xd + bad*xa*xd + ub + us
                p = min(max(sig(eta), 1e-9), 1-1e-9)
                X.append([1.0, float(xa), float(xd), float(xa*xd)])
                y.append(1 if rng.random() < p else 0); cs += 1
        csizes.append(cs)
    n = len(X)
    beta = [0.0]*K
    for _ in range(40):
        XtWX = [[0.0]*K for _ in range(K)]; XtWz = [0.0]*K
        for t in range(n):
            x = X[t]; eta = sum(b*xi for b, xi in zip(beta, x))
            p = min(max(sig(eta), 1e-9), 1-1e-9)
            w = p*(1-p); z = eta + (y[t]-p)/w
            for i in range(K):
                wxi = w*x[i]; XtWz[i] += wxi*z
                for j in range(K): XtWX[i][j] += wxi*x[j]
        BI = inv(XtWX)
        nb = [sum(BI[i][j]*XtWz[j] for j in range(K)) for i in range(K)]
        done = max(abs(a-b) for a, b in zip(nb, beta)) < 1e-8
        beta = nb
        if done: break
    XtWX = [[0.0]*K for _ in range(K)]
    resid = [0.0]*n
    for t in range(n):
        x = X[t]; eta = sum(b*xi for b, xi in zip(beta, x))
        p = min(max(sig(eta), 1e-9), 1-1e-9)
        w = p*(1-p); resid[t] = y[t]-p
        for i in range(K):
            for j in range(K): XtWX[i][j] += w*x[i]*x[j]
    BI = inv(XtWX)
    meat = [[0.0]*K for _ in range(K)]
    idx = 0
    for csz in csizes:
        g = [0.0]*K
        for _ in range(csz):
            r = resid[idx]; x = X[idx]
            for i in range(K): g[i] += x[i]*r
            idx += 1
        for i in range(K):
            for j in range(K): meat[i][j] += g[i]*g[j]
    v = sum(BI[3][m]*meat[m][q]*BI[q][3] for m in range(K) for q in range(K))
    se = math.sqrt(max(v, 1e-12))
    return 1 if abs(beta[3]/se) > Z_CRIT else 0

def power(B, S, bt, sims, base=0):
    args = [(B, S, bt, base+i) for i in range(sims)]
    with mp.Pool(64) as pool:
        r = pool.map(sim_one, args, chunksize=2)
    return sum(r)/len(r)

if __name__ == "__main__":
    SIMS = 400
    print("ASSUMED generative pattern for sizing ONLY: logit = 0 + 0.9*A - 1.2*D + Delta*A*D")
    print("B    S   Delta(logOR)   power(cluster-robust Wald, %d sims)" % SIMS)
    for B in (50, 100, 150, 200):
        for delta in (0.6, 0.9, 1.2):
            pw = power(B, 3, (0.0, 0.9, -1.2, delta), SIMS, base=B*1000+int(delta*100))
            print(f"{B:4d}  3      {delta:.1f}         {pw:.2f}")
